const first = $input.first()?.json;
const isEmpty = !first || Object.keys(first).length === 0;

const dt = DateTime.now()
  .setZone('Europe/Samara')
  .setLocale('ru');

const weekday = dt.weekdayLong;
const weekdayCap = weekday.charAt(0).toUpperCase() + weekday.slice(1);

const today = `${dt.toFormat('dd.MM.yyyy')}, ${weekdayCap}`;

const res = {
  chatId: $('Set Default Data').first().json.chatId,
  text: $('Set Default Data').first().json.text, 
  today,
  role_code: 'NOT_ALLOWED',
  tg_id: null
};
const firstJson = !isEmpty ? first : {} 

return [{ json: {...res, ...firstJson} }];

